-- Platsbeskrivningar, omgång 5 (46 platser). Skrivna utifrån platsernas egna hemsidor.
-- Kort text högst 7 ord, lång 70–100 ord.
begin;
update public.places set short_description = 'Lägenheter på korsvirkesgård vid Stenshuvud', description = 'Kastanjegården ligger på Stenshuvudsvägen strax utanför Kivik, omgiven av en äppelodling mitt i hjärtat av Österlen. Gården är en trelängad korsvirkesgård med utsikt över Österlens böljande lövskogar. Här hyrs barnvänliga lägenheter ut, som passar bra för familjer och grupper som vill vara nära naturen, havet och Stenshuvuds nationalpark. Kastanjegården har tagit emot gäster sedan 2015 och erbjuder ett personligt mottagande. Lägenheterna bokas direkt via hemsidan, där priset är som bäst, men finns även på Booking.com och Airbnb.' where id = 257; -- Kastanjegården Bed and Breakfast
update public.places set short_description = 'Vandrarhem med naturen som granne', description = 'Kuskahusen är ett vandrarhem nära Brösarp, med naturens stillhet som närmaste granne. Vandrarhemmet har öppet året runt och erbjuder rum med bäddade sängar, ett komplett gästkök där gästerna lagar sin egen mat och en mysig matsal. Härifrån når man fina vandringar i det skånska landskapet. Kring högtiderna erbjuds en stilla jul och ett raketfritt nyår för den som vill fira med naturen, lugnet och varandra i fokus. Rum bokas via deras hemsida, där även aktuella erbjudanden finns.' where id = 260; -- Kuskahusen Vandrarhem
update public.places set short_description = 'Livsmedelsbutik med ombud i Löderup', description = 'Handlar''n i Löderup är byns livsmedelsbutik på Storgatan. Förutom dagligvaror finns här ombud för PostNord, DSV, DHL och Bring, och man kan hämta ut varor från både Systembolaget och apoteket. Butiken har öppet alla dagar i veckan, med längre öppettider på vardagar och kortare på lördagar och söndagar. Löderup ligger på södra Österlen nära kusten, Kåseberga och Sandhammaren, vilket gör butiken till ett praktiskt stopp för den som bor eller semestrar i trakten. Frågor kan skickas via hemsidan.' where id = 262; -- Handlarn i Löderup
update public.places set short_description = 'Gammaldags köttbutik med manuell betjäning', description = 'Österlens Kött & Vilt i Brösarp är en gammaldags skånsk köttbutik med manuell betjäning och gamla recept. Här finns hängmörat nötkött, fläsk och lamm, och under säsong även vilt. Allt säljs som färskvaror direkt från disken, där man själv väljer sin bit att ta hem och laga. Råvarorna kommer från producenter i trakten och slaktas på mindre slakterier, vilket ger hög kvalitet och korta transporter, bra både för kunden och miljön. Butiken har öppet tisdag till lördag.' where id = 267; -- Österlens Kött & Vilt Brösarp
update public.places set short_description = 'Färsk fisk från vagn i Brantevik', description = 'Branteviks Fisk är ett familjeägt företag som startade 2017 och har över 30 års erfarenhet av fiskbranschen. Från sin vagn mitt i fiskeläget Brantevik säljer de färsk fisk och färdiga fiskrätter. De arbetar bara med lokala och hållbara råvaror för att kunna erbjuda fisk av hög kvalitet. Branteviks Fisk erbjuder också catering till fester och andra tillfällen. Det är ett bra stopp för den som vill köpa med sig färsk fisk hem eller till sommarstugan efter en promenad i Brantevik.' where id = 269; -- Branteviks Fisk
update public.places set short_description = 'Delikatessbutik med lunchbuffé i Simrishamn', description = 'Börje & Olsson Skafferi ligger på Storgatan i Simrishamn och har delikatessdiskar, catering och en lunchbuffé som serveras måndag till lördag. Man kan äta lunch på plats eller plocka ihop mat från buffén att ta med hem, och då betalar man efter vikt. Det går också att ringa och beställa från diskarna, buffén och cateringmenyn, så plockar personalen ihop allt efter önskemål. Butiken har öppet sex dagar i veckan och håller stängt på söndagar och helgdagar. Här finns mycket gott för vardag och fest.' where id = 270; -- Börje & Olsson Skafferi
update public.places set short_description = 'Svenska kryddor, gårdsbutik och glasshus', description = 'Österlenkryddor i Köpingebro odlar och förädlar äkta svenska kryddor, från spadtaget till kryddhyllan, med fokus på hantverksmässig kvalitet. I gårdsbutiken kan man handla på plats, och i glasshuset finns deras prisbelönta glass. Hela sortimentet av kryddor och eteriska oljor finns även i en webbutik, tillsammans med produkter från utvalda svenska leverantörer av råvaror och mathantverk. Gården ordnar också evenemang och aktiviteter under året. Kryddorna passar både till vardagsmat och som present från Österlen.' where id = 271; -- Österlenkryddor
update public.places set short_description = 'Gårdsbutik med grönsaker, öppen dygnet runt', description = 'Örnahusens Gårdsbutik är en liten butik för färska och närproducerade grönsaker i Örnahusen, strax söder om Skillinge och Simrishamn. Här finns alltid ett brett utbud av grönsaker efter säsong och ägg från gårdens egna höns. Butiken har öppet året runt och dygnet runt, så man kan handla när det passar. Gårdsbutiken drivs av Krister Persson. Den är ett praktiskt stopp för den som vill ha färska råvaror direkt från jorden till middagen, oavsett om man bor i trakten eller semestrar här.' where id = 274; -- Örnahusens Gårdsbutik
update public.places set short_description = 'Hemtrevligt charkuteri på Österlen', description = 'Sälshögscharken är ett hemtrevligt charkuteri nära Tomelilla där alla produkter görs för hand. De som driver charkuteriet har tillsammans över 50 års erfarenhet av branschen, och de förverkligade sin dröm om ett gemensamt charkuteri våren 2019. I butiken säljs charkuteriets egna produkter. Sälshögscharken erbjuder även grillad gris till fester och större sällskap. Mer information om sortimentet och vägbeskrivning finns på hemsidan. Det är ett bra stopp för den som vill handla med sig lokalt gjord chark.' where id = 275; -- Sälshögs charken
update public.places set short_description = 'Äkta skånsk senap och gårdsbutik', description = 'Petersborgs Gård ligger nära Smedstorp på Österlen, där de odlar senap och tillverkar en äkta skånsk senap. Senapen säljs i gårdsbutiken, som också har ett stort sortiment av andra närproducerade varor. Gårdsbutiken har öppet på fredagar och lördagar. Senapsprodukterna kan även köpas i deras webbutik och i en butik i Lunds saluhall. Gården är med i Matrundan Österlen. Det är ett bra stopp för den som vill handla lokal mat och ta med sig en smak av Österlen hem.' where id = 276; -- Petersborgs Gård
update public.places set short_description = 'Sjöfartsmuseum om Branteviks segelflotta', description = 'Sjöfartsmuseet Hoppet berättar om Brantevik, det yngsta fiskeläget vid Österlens kust, som kring sekelskiftet 1900 hade Sveriges till antalet största flotta av lastdragande segelfartyg. Som mest hörde 118 skutor hemma här samtidigt. Genom målningar, modeller och dokument berättar museet hur byn växte och hur detta kunde gå till. Museet har öppet några eftermiddagar i veckan under sommaren, och den som vill komma vid andra tider kan kontakta museet. Lokalen kan också hyras.' where id = 277; -- Sjöfartsmuseet Hoppet
update public.places set short_description = 'Klädbutik med märkeskläder i Tomelilla', description = 'Eckerlunds Kläder i Tomelilla är en klädbutik på 700 kvadratmeter med märkeskläder för både henne och honom. Butiken erbjuder kvalitet, ett stort urval och personlig service. Kollektionerna byts efter säsong, så det finns alltid något nytt för våren, sommaren, hösten eller vintern. Eckerlunds lägger ut nyheter och erbjudanden på sin Facebooksida. Butiken är ett bra stopp för den som vill handla kläder på Österlen och få hjälp av kunnig personal att hitta rätt.' where id = 278; -- Eckerlunds Kläder
update public.places set short_description = 'Cidergård med provningar och ciderbar', description = 'Forse Cidergård nära Rörum gör svensk hantverkscider, på en plats med unik natur på gränsen mellan skog och öppet landskap. Ägarna drev tidigare Rörumsro musteri i tio år med egna ekologiska odlingar. Här kan man boka ciderprovning och en tur på gården, följa med under skördetiden och se hur drycken blir till. I ciderladan finns en ciderbar, och man kan ha picknick med lokalt mathantverk i äppellunden. Gården har en gårdsbutik och ordnar också föreställningar och evenemang.' where id = 281; -- Forse Cidergård
update public.places set short_description = 'Fårgård med gårdsbutik och fårsafari', description = 'Åsgård ligger strax utanför Onslunda och drivs av Charlotte och Kalle, som är deltidslantbrukare. På gården håller de omkring hundra tackor av rasen gotlandsfår, och vallhundarna Greta och York hjälper till med fåren. De odlar också ekologiskt dinkel och emmer. I gårdsbutiken säljs det som odlas och produceras på gården, som lammkött, dinkelmjöl, ullprodukter, lamm- och fårskinn och grönsaker. Här kan man också bo på lantgård och följa med på fårsafari.' where id = 282; -- Åsgårds Gårdsbutik
update public.places set short_description = 'Olivoljor och italienska delikatesser', description = 'Sannas Italien är en liten butik på en äng på Hagestad mossaväg nära Löderup, där Sanna Töringe säljer olivoljor och delikatesser från olika regioner i Italien. Allt började med ett litet stenhus i södra Italien. I dag besöker Sanna små gårdar och handlar direkt från producenterna. I butiken finns ett tjugotal olika olivoljor och oliver från olika delar av Italien. Sanna arrangerar även resor i Italien för den som vill uppleva landet, maten och olivodlingarna på nära håll.' where id = 286; -- Sannas Italien
update public.places set short_description = 'Lågprisvaruhus för hela familjen', description = 'Bo Ohlsson i Tomelilla är ett lågprisvaruhus med omkring 10 000 kvadratmeter butiksyta och 100 000 olika artiklar. Här finns allt från presenter, kläder och accessoarer till verktyg och saker för hem och trädgård. Företaget startades 1947 av Bror, far till Bo Ohlsson, och har vuxit till ett varuhus för hela familjen. Det finns gratis parkering, och varuhuset har öppet alla dagar. Varje vecka finns kampanjer, och här finns även mat och dryck för den som vill ta en paus.' where id = 289; -- Bo Ohlsson i Tomelilla
update public.places set short_description = 'Trädgårdsbutik mitt i Simrishamn', description = 'MaKalösa Trädgårdar är en trädgårdsoas på Storgatan mitt i Simrishamn, där man hittar det mesta till sin trädgård. I butiken och trädgården finns växter och tillbehör som följer säsongen. MaKalösa Trädgårdar erbjuder även olika trädgårdstjänster för den som vill ha hjälp hemma. Butiken har öppet de flesta dagar i veckan, med särskilda tider under sommaren och vid helgdagar. Alla beställningar görs via telefon. Det är ett bra stopp för den som vill hitta något nytt till trädgården eller balkongen.' where id = 293; -- MT MaKalösa Trädgårdar
update public.places set short_description = 'Familjegård med potatis och gårdsbutik', description = 'Lavelund är ett familjeföretag i Köpingebro med en gårdsbutik. Lantbruket startades 1956 av Lave Knutsson, och sonen Jan tog över 1991. Gården drivs i dag av Jan och Anna-Maria Knutsson, och Jans föräldrar hjälper fortfarande till ibland. I gårdsbutiken säljs gårdens produkter, och potatisen har en särskild plats. På hemsidan finns en guide till de olika potatissorterna och vad de passar till. Lavelund är ett bra stopp för den som vill handla potatis och andra råvaror direkt från gården.' where id = 299; -- Lavelunds Gårdsbutik
update public.places set short_description = 'Trädgårdsdesign och butik nära Smedstorp', description = 'I vått och torrt är en butik med trädgårdsdesign och inredning nära Smedstorp. Butiken har säsongsöppet från påsk och under sommaren, men den som kommer förbi under resten av året kan ringa, så försöker de ordna ett besök. Under vintern deltar de i julmarknader runt om i trakten, där man kan hitta deras saker. Bilder från butiken och nyheter om vad som händer läggs ut på Facebook och Instagram. Det är ett ställe för den som gillar trädgård och lantlig inredning.' where id = 303; -- I vått och torrt Trädgård och inredning
update public.places set short_description = 'Garnbutik och gård med ställplatser', description = 'Blästorps Gård är en klassisk skånegård från 1800-talet nära Borrby, där det stora gamla spannmålsmagasinet ger gården dess karaktär. Här finns Maruchi Fibres garnbutik, som har öppet året runt med ett noga utvalt sortiment av garner. Gården har lokaler för fester, evenemang, bröllop och konserter, och det finns ställplatser med el för husbilar. Under sommaren ordnas evenemanget Garn på Gården, och då finns även semesterboende, vintagemarknad och café. Kommande evenemang läggs ut på Instagram.' where id = 305; -- Blästorps gårds B&B
update public.places set short_description = 'Southern comfort food och vedrök', description = 'Smoked by Joe nära Hammenhög vill vara mer än en restaurang, en mötesplats där den skånska myllan möter southern comfort food. Här brinner elden året om, och maten präglas av doften av vedrök. Restaurangen samarbetar med lokala aktörer som delar synen på kvalitet och hållbarhet, och engagerar sig i initiativ som ger människor utanför arbetslivet nya möjligheter. Visionen sammanfattas i orden mer rök, mer värme och mer mänsklighet. Bord bokas via restaurangens hemsida.' where id = 308; -- Smoked by Joe
update public.places set short_description = 'Restaurang och picklebar i Borrby', description = 'Köpmangatan 6 är en restaurang i Borrby som serverar lunch på fredagar och lördagar och middag på lördagkvällar. Lunchmenyn kan till exempel innehålla schnitzel eller friterad torsk, och det finns alltid en barnmeny. På torsdagar och fredagar har Picklebaren öppet på kvällen. Bakom Köpmangatan 6 står också Kyhls Strandbar. Restaurangen ordnar evenemang och provningar under året och skräddarsyr gärna provningar för sällskap. Bord bokas via hemsidan, där även kvällsmeny och vinlista finns.' where id = 315; -- Köpmangatan 6
update public.places set short_description = 'Surflektioner och surfcamp på Österlen', description = 'Österlen Surfcenter erbjuder surflektioner och surfcamp, både på Österlen och i Portugal. Grundaren upptäckte surfing för omkring tio år sedan, under en tuff period i livet, och vill i dag dela med sig av den glädje och styrka som surfingen gav. Ledorden är kärlek, värme och vågor. Lektionerna passar både den som vill prova på för första gången och den som vill bli bättre. Mer information om lektioner, camp och bokning finns på hemsidan.' where id = 320; -- Österlen Surfcenter
update public.places set short_description = 'Cykelbutik, verkstad och cykeluthyrning', description = 'Österlens Cykel i Simrishamn sköter allt som har med cyklar att göra. I butiken finns nya och begagnade cyklar, bland annat från Skeppshult och Gazelle, och ett brett sortiment av reservdelar och tillbehör som hjälmar, korgar, belysning och cykelväskor. I verkstaden görs service och reparationer. Här kan man också hyra cykel för att ta sig runt på Österlen, vilket passar bra för den som vill upptäcka trakten på två hjul. På hemsidan finns även tips om att äta, bo och göra.' where id = 321; -- Österlens Cykel
update public.places set short_description = 'Cykeluthyrning och guidning vid Ravlunda', description = 'Ravlunda Cykel är ett litet och flexibelt företag med många års erfarenhet av cykeluthyrning och guidning. De hyr ut cyklar och tar gärna emot stora grupper. Cyklarna kan levereras och hämtas, och guidade turer går bland annat till Kivik, Haväng, Brösarps backar, Kristianstad, Simrishamn och Ystad. Ravlunda Cykel samarbetar med flera boenden i trakten. Det är ett bra sätt att upptäcka norra Österlens natur och kust i lugn takt. Bokning görs via telefon.' where id = 322; -- Ravlunda Cykel
update public.places set short_description = 'Skånes största nöjespark och sommarland', description = 'Tosselilla är en nöjespark och ett sommarland i skön natur mitt på Österlen, nära Tomelilla, och beskriver sig som Skånes största. Här finns massor av aktiviteter för både stora och små, med bad, lek och åkattraktioner. Alla attraktioner och aktiviteter ingår i entrébiljetten, utom gokart som kostar extra. Man kan bada, åka och leka hur mycket man vill hela dagen. Tosselilla har säsongsöppet under sommaren, och biljetter köps på hemsidan.' where id = 327; -- Tosselilla Sommarland
update public.places set short_description = 'Utomhusgokart i Tomelilla', description = 'Tomelilla Hyrkart är en gokartbana utomhus i Tomelilla, som drivs av Tobbe, Jenny, Olle och Karin. Här kan man köra ett eller flera åk på tio minuter, och det finns mindre gokarts för barn. För grupper finns tävlingar, och på hemsidan kan man se de bästa varvtiderna. Banan har öppet för tidsbokning, vilket innebär att man ringer och bokar en tid som passar, och de kan öppna de flesta dagar. Gokart är ett roligt sätt att fira kalas eller göra något med kompisgänget.' where id = 330; -- Tomelilla Hyrkart
update public.places set short_description = 'Hedlandsbana med havsutsikt vid Vik', description = 'Djupadal är Österlens Golfklubbs hedlandsbana med 18 hål, byggd på ren sandjord med utsikt över havet. Här spelar man bland äppelträd, vilket får tankarna att gå till sydligare breddgrader. Banan ligger vid Viks fiskeläge, på andra sidan landsvägen från klubbens andra bana, Lilla Vik. På hemsidan finns banguide, banstatus, slopetabeller och spelstrategi för banan, och starttid bokas online. Vid dimma eller frost råder normalt spelförbud, så det är bra att kolla banstatus innan man åker dit.' where id = 331; -- Österlens Golfklubb - Djupadal
update public.places set short_description = 'Bed and breakfast nära Kåseberga', description = 'Peppinge Bed & Breakfast har erbjudit boende på Österlen sedan 2006 och drivs i dag av Micke och Rickard, som kom hit från Stockholm. Här finns sju rum med 19 sängplatser, och flera rum har plats för extrasängar, vilket passar familjer, par och mindre sällskap. Boendet ligger nära Kåseberga, Ales stenar och stränderna. Det är djurfritt för att vara allergivänligt, men den som kommer med husbil får ta med hunden. Här finns också glamping, ett galleri och konferens.' where id = 334; -- Peppinge B&B
update public.places set short_description = 'Butik, B&B och galleri vid strandbadet', description = 'Strandbadsgården ligger vid Löderups strandbad och rymmer en butik, ett bed and breakfast och ett galleri. I butiken finns tyger, smycken och kläder, både nytt och second hand. På loftet finns fyra rum med egen dusch och toalett och nya sängar, och lakan och handdukar ingår. Frukost serveras på morgonen, och gästerna kan grilla och använda kyl, frys och mikrovågsugn. Man bor vägg i vägg med galleriet, och det är bara en kort promenad till stranden.' where id = 335; -- Strandbadsgården B&B
update public.places set short_description = 'Semesterby med stugor och gårdssviter', description = 'Mälarhusen Semesterby ligger nära stranden längs Östra Kustvägen i Löderup, mitt emellan Ystad och Simrishamn. Här bor man i moderna stugor eller nybyggda gårdssviter, mitt i det vackra Österlen med fina utflyktsmål i närheten. På anläggningen finns minigolf, boule och lekplatser, och det går att ladda elbil. Tillval som slutstädning, lakan och handdukar samt hund bokas separat. Semesterbyn passar bra för familjer som vill bo nära havet och ha aktiviteter för barnen direkt utanför dörren.' where id = 336; -- Mälarhusen Semesterby Österlen. Stugor & Gårdssviter
update public.places set short_description = 'Bed and breakfast med milsvid utsikt', description = 'Österlens Karlsgård, i folkmun Karlsgården, är ett bed and breakfast nära Örum, precis ovanför Löderup och nedanför Hannas. Gården drivs av Fredrik Lagerberg tillsammans med familjen och hunden, och utsikten är milsvid. Här finns tolv rum, varav nio med eget badrum, med plats för omkring 30 personer. Läget beskrivs som nära till allt men tillräckligt långt bort, mitt på Österlen mellan Ystad och Simrishamn. Karlsgården passar både för en lugn semester och för större sällskap.' where id = 337; -- Österlens Karlsgård
update public.places set short_description = 'Gård för konferenser, kurser och fest', description = 'Borregården ligger vackert mellan milsvida åkrar strax utanför Borrby. Här arrangeras konferenser, kurser, middagsbjudningar och privata helger, och man kan hyra hela huset för sig och sina nära och kära. Gården erbjuder bland annat pastakurser och har en healingstudio, Saybon. Läget är avskilt, tyst och lugnt, men ändå nära Österlens sevärdheter. Borregården beskriver sig som opretentiös, generös och ambitiös, en plats där nästan allt är möjligt. Bokning och mer information finns på hemsidan.' where id = 338; -- Borregården B&B
update public.places set short_description = 'Bed and breakfast med havsutsikt', description = 'Skönadal B&B ligger mellan Brantevik och Skillinge, med utsikt över Österlens böljande landskap och havet. När vädret är klart syns Bornholm vid horisonten. Här finns sju fräscha dubbelrum och en lägenhet i olika storlekar, som passar både par, familjer och mindre sällskap. Alla rum har eget badrum och en uteplats med fin utsikt. Boendet ligger i en lugn lantlig miljö, nära stränder, kultur och lokala restauranger. På hemsidan finns tips om vad man kan se och göra.' where id = 341; -- Skönadal B&B
update public.places set short_description = 'B&B, café och mat i Brantevik', description = 'Hörnan på Brantevik är ett hus från 1874 i fiskeläget Brantevik, med havsutsikt och ett personligt bemötande. Här finns ett bed and breakfast, och man serverar frukost, fika och kärleksfullt lagad mat. När solen värmer öppnar uteserveringen, och här finns även lite shopping. Öppettiderna varierar över året, och ibland har de öppet alla dagar från morgon till kväll. Boende bokas via Booking.com. Det är ett trevligt ställe att stanna till på efter en promenad längs kusten i Brantevik.' where id = 343; -- Hörnan på Brantevik
update public.places set short_description = 'Rum med självhushåll i Hammenhög', description = 'Huset på Hörnet är ett charmigt boende från 1897 i centrala Hammenhög. Sedan december 2024 ägs huset av Pia och Dan Lindgren, som älskar Österlen och kreativiteten här. Gästerna bor i dubbelrum på övervåningen och kan laga enklare måltider eller packa en utflyktskorg i det gemensamma köket. Boendet har öppet hela året och passar för en avkopplande semester eller en kortare tripp. Målet är att erbjuda en enkel och prisvärd övernattning mitt på Österlen.' where id = 344; -- Huset på Hörnet Hammenhög
update public.places set short_description = 'Litet boutiquehotell i Gladsax', description = 'Gladsax Gårdshotell är ett litet, personligt boutiquehotell i den gamla byn Gladsax, strax utanför Simrishamn. Här finns fyra rymliga rum med unik inredning och handplockad design, och alla har en egen uteplats där kvällssolen dröjer sig kvar. På morgonen serveras frukostbuffé i det privata köket eller ute i trädgården. Hotellet vänder sig till den som söker stillhet, ljus och närhet till landskapet, och mer än bara en plats att sova på. Rum bokas via hotellets hemsida.' where id = 345; -- Gladsax Gårdshotell
update public.places set short_description = 'B&B för vuxna med pool och havsutsikt', description = 'Torsborgs Gård är ett personligt bed and breakfast som ligger på en höjd ovanför havet, intill Bäckhalladalens naturreservat. Härifrån har man panoramautsikt över Östersjön och böljande ängar. För att värna om stillheten tar Torsborg bara emot vuxna. Det finns en uppvärmd pool för ett dopp efter dagens utflykter. Från gården är det nära till Simrishamn och hela Österlen, från Haväng i norr till Ales stenar i söder. Bokning görs direkt på hemsidan för bästa pris.' where id = 346; -- Torsborgs Gård
update public.places set short_description = 'Personligt bed and breakfast i Skåne-Tranås', description = 'Munkamöllan är ett personligt bed and breakfast i Skåne-Tranås, mitt på Österlen, omgivet av öppna landskap, lugn och stillhet. Här bor man i unika rum med egen karaktär, där vardagen får stanna utanför. Frukosten serveras i lugn takt, så att gästerna kan planera en dag med natur, utflykter eller ingenting alls. Munkamöllan tar också emot bröllop, konferenser och andra evenemang i en personlig miljö. Rum och tillfällen bokas via hemsidan, där även alla rum presenteras.' where id = 350; -- Munkamöllan Logi Skåne Tranås
update public.places set short_description = 'Gårdshotell och restaurang i Kivik', description = 'Ekenäs Gård är en familjedriven gård på Stenshuvudsvägen i Kivik, nära havet och omgiven av blomsterängar, bokskog och äppellundar. Här finns vackert inredda gårdssviter i två plan för den som vill bo personligt. Restaurangen på gården fokuserar på hantverk och råvaror från gårdens egen odling. Värdarna vill att gästerna ska känna sig som hemma, och tar hand om dem som om de vore sina bästa vänner. Rum, erbjudanden och bord bokas via hemsidan.' where id = 351; -- Ekenäs Gård på Österlen
update public.places set short_description = 'Bed and breakfast och keramik vid Stenshuvud', description = 'Elisetorp är en gammal, liten kringbyggd skånegård nära Kivik som en gång var lantbruk. Gården ställde senare om till fruktodling, och i dag satsar ägarna på bed and breakfast och keramik. Som gäst har man en fantastisk utsikt över äppelträden, Stenshuvuds nationalpark och havet, och med lite tur kan man se Bornholm. Elisetorp är en lugn plats mitt i naturen nära Kivik. På hemsidan finns viktig information, vägbeskrivning och bokning.' where id = 352; -- Elisetorp
update public.places set short_description = 'Bed and breakfast ovanför Kivik', description = 'Adagio på Österlen är ett bed and breakfast strax ovanför Kivik på Linderödsåsen, med en hemlik miljö. Härifrån har man milsvid utsikt över Stenshuvud, Södra Mellby kyrkby och en glimt av Hanöbukten. Promenadstigar leder ner till Kivik, och det är nära till Kungagraven, Stenshuvud, Haväng och Brösarps backar. Via samarbetspartnern Ravlunda Cykel kan man hyra cykel och ge sig ut på en picknicktur. Adagio passar den som vill bo lugnt men nära allt.' where id = 353; -- Adagio på Österlen
update public.places set short_description = 'Familjeägt frukosthotell i Kivik', description = 'Kaptenshuset är ett litet familjeägt frukosthotell i Kivik, i hjärtat av Österlen. Från och med 2026 drivs hotellet av Per och Ann Elg Kjellberg med team, med fokus på personlig service och en varm stämning. Här finns dubbelrum och familjerum med extrasängar, och även stugor. Rummen kombinerar modern komfort med charmiga detaljer från trakten. Kaptenshuset passar för en avkopplande vistelse nära Kiviks hamn och Stenshuvud. Bokning görs direkt via hotellets hemsida.' where id = 354; -- Kaptenshuset Hotell
update public.places set short_description = 'Nyrenoverade rum på gård i Kivik', description = 'Killegården på Kivik har tio nyrenoverade rum i olika storlekar, alla med egen dusch och toalett, AC, smart-tv och kylskåp. Sedan hösten 2021 drivs gården av Lisa och Per, som blev förälskade i stället vid första besöket. Här ska gästerna känna sig som hemma, och stress är bannlyst. På innergården kan man njuta av ett glas och ta det lugnt. Killegården bjuder på must, cider och juice gjord på äpplen från trakten, eftersom Kivik är känt för sina äpplen.' where id = 355; -- Killegården på Kivik
update public.places set short_description = 'Hotell med spa och havsutsikt i Kivik', description = 'Kiviks Hotell ligger på en höjd ovanför stranden i Kivik, med milsvid utsikt över havet. Hotellet har rum, restaurang, spa och konferens, och här finns också konst och en trädgård i italiensk nyrenässans. Huset byggdes 1908 som villan Emiliero, åt advokaten Åke Hjort och hans hustru Emilia. Hotellet vill vara mer än ett hotell, en plats för upplevelser för alla sinnen, med god sömn, soluppgångar över havet och smaker från Österlen. Bokning sker via hemsidan.' where id = 356; -- Kiviks Hotell Konferens och Spa
update public.places set short_description = 'B&B för vuxna på 1700-talsgård', description = 'Rubensholm är ett bed and breakfast i en trelängad korsvirkesgård från 1700-talet, längs väg 19 mellan Brösarp och Skåne-Tranås. Gården omges av lummig grönska, och på den kullerstensbelagda innergården står ett gammalt vårdträd. Rubensholm tar emot vuxna gäster som vill uppleva Österlen och ha en trivsam plats att återvända till efter dagens utflykter. Gården har en lång historia, och på hemsidan berättar ägarna om hur livet på gården har sett ut genom århundradena.' where id = 359; -- Rubenholm B&B
commit;
